1080	import 'dart:async';
1081	
1082	/// Story 1.5 — lets `core/network`'s `ApiClient` signal a mid-session
1083	/// `AUTH_EXPIRED` without importing anything from `features/auth` (RNF06:
1084	/// the domain/data layers of a feature are the only things allowed to know
1085	/// about each other across that boundary, never the other way from core).
1086	/// `SessionRepositoryImpl` is the one bridge that turns an event on
1087	/// [expiredEvents] into the epic's single `SessionStatus.expired` value on
1088	/// its own `statusStream` (Design Notes).
1089	///
1090	/// Pure Dart, no Flutter import — same constraint `ApiClient`/`Failure`
1091	/// already hold in `core/`.
1092	abstract class SessionExpiryNotifier {
1093	  /// Broadcast stream of expiry events. Unlike `SessionRepository
1094	  /// .statusStream`, this carries no replay semantics: it is a one-shot
1095	  /// signal per expiry, not a status a late subscriber needs to catch up
1096	  /// on — only `SessionRepositoryImpl`'s single long-lived subscription
1097	  /// (wired at construction) is expected to listen.
1098	  Stream<void> get expiredEvents;
1099	
1100	  /// Signals that the current session just expired mid-use (a non-boot
1101	  /// `AUTH_EXPIRED` response). Never throws.
1102	  void notifyExpired();
1103	
1104	  /// Releases the underlying stream resource.
1105	  Future<void> dispose();
1106	}
1107	
1108	/// Default implementation — a broadcast `StreamController` wrapped behind
1109	/// the port above.
1110	class SessionExpiryNotifierImpl implements SessionExpiryNotifier {
1111	  final StreamController<void> _controller = StreamController<void>.broadcast();
1112	
1113	  @override
1114	  Stream<void> get expiredEvents => _controller.stream;
1115	
1116	  @override
1117	  void notifyExpired() {
1118	    // Guards against a call racing `dispose()` (wired to `get_it`'s
1119	    // `sl.reset()`) — without this, a late `.add()` after `.close()` would
1120	    // throw an unhandled `StateError` instead of just being a no-op on an
1121	    // already-torn-down notifier (same rationale as `SessionRepositoryImpl
1122	    // ._emit`).
1123	    if (_controller.isClosed) {
1124	      return;
1125	    }
1126	    _controller.add(null);
1127	  }
1128	
1129	  @override
1130	  Future<void> dispose() => _controller.close();
1131	}
